import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    m, n = int(data[0]), int(data[1])
    g = [data[2 + i] for i in range(m)]
    INF = 10 ** 9
    f = [[INF] * n for _ in range(m)]
    dq = deque()
    for i in range(m):
        for j in range(n):
            if g[i][j] == '1':
                f[i][j] = 0
                dq.append((i, j))
    while dq:
        i, j = dq.popleft()
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= a < m and 0 <= b < n and g[a][b] == '0' and f[a][b] == INF:
                f[a][b] = f[i][j] + 1
                dq.append((a, b))

    def ok(d):
        if f[0][0] <= d:
            return False
        seen = [[False] * n for _ in range(m)]
        seen[0][0] = True
        q = deque([(0, 0, d)])
        while q:
            i, j, t = q.popleft()
            t += 1
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < m and 0 <= b < n and not seen[a][b] and g[a][b] != '2':
                    if a == m - 1 and b == n - 1:
                        if f[a][b] >= t:
                            return True
                        continue
                    if f[a][b] > t:
                        seen[a][b] = True
                        q.append((a, b, t))
        return False

    if ok(m * n):
        print(10 ** 9)
        return
    if not ok(0):
        print(-1)
        return
    lo, hi = 0, m * n
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

