    def fmt(g):
        return str(len(g)) + ' ' + str(len(g[0])) + '\n' + '\n'.join(''.join(r) for r in g)

    def rand_grid(m, n, nf, pr):
        g = [['2' if rng.random() < pr else '0' for _ in range(n)] for _ in range(m)]
        for _ in range(nf):
            g[rng.randrange(m)][rng.randrange(n)] = '1'
        g[0][0] = '0'
        g[m - 1][n - 1] = '0'
        return g

    def pocket(M, N, noise):
